/** Terjemahkan label lesson: ganti bagian Indonesia setelah " · " atau seluruh teks. */
export function enLabel(s) {
  if (EN_LABEL[s]) return EN_LABEL[s];
  return s
    .split(" · ")
    .map(part => EN_LABEL[part] || part)
    .join(" · ")
    .replace(/\bAngka\b/g, "Numbers")
    .replace("senang bisa membantu · layanan & transportasi", EN_LABEL["senang bisa membantu · layanan & transportasi"]);
}
